ta_type, 12 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'record_sha256' AS column_name, 'STRING' AS data_type, 13 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'processing_key' AS column_name, 'STRING' AS data_type, 14 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'pipeline_version' AS column_name, 'STRING' AS data_type, 15 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'quality_policy_sha256' AS column_name, 'STRING' AS data_type, 16 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'truck_id' AS column_name, 'STRING' AS data_type, 17 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'event_time_unzoned' AS column_name, 'TIMESTAMP_NTZ' AS data_type, 18 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'latitude' AS column_name, 'DOUBLE' AS data_type, 19 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'longitude' AS column_name, 'DOUBLE' AS data_type, 20 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'plow_active' AS column_name, 'BOOLEAN' AS data_type, 21 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'spreader_active' AS column_name, 'BOOLEAN' AS data_type, 22 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'engine_active' AS column_name, 'BOOLEAN' AS data_type, 23 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'payload_occurrences' AS column_name, 'BIGINT' AS data_type, 24 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'has_repeated_payload' AS column_name, 'BOOLEAN' AS data_type, 25 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'is_repeated_header' AS column_name, 'BOOLEAN' AS data_type, 26 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'quality_status' AS column_name, 'STRING' AS data_type, 27 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'quality_issues' AS column_name, 'STRING' AS data_type, 28 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_silver' AS table_name, 'quality_warnings' AS column_name, 'STRING' AS data_type, 29 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'processing_key' AS column_name, 'STRING' AS data_type, 0 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'source_version_id' AS column_name, 'STRING' AS data_type, 1 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'source_file_name' AS column_name, 'STRING' AS data_type, 2 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'source_file_sha256' AS column_name, 'STRING' AS data_type, 3 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'metadata_json' AS column_name, 'STRING' AS data_type, 4 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'policy_json' AS column_name, 'STRING' AS data_type, 5 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'status' AS column_name, 'STRING' AS data_type, 6 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'last_successful_stage' AS column_name, 'STRING' AS data_type, 7 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'attempts' AS column_name, 'BIGINT' AS data_type, 8 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'bronze_rows' AS column_name, 'BIGINT' AS data_type, 9 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'silver_rows' AS column_name, 'BIGINT' AS data_type, 10 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'error_code' AS column_name, 'STRING' AS data_type, 11 AS ordinal_position UNION ALL SELECT 'winterops_v2_dev_manifest' AS table_name, 'updated_at_utc' AS column_name, 'TIMESTAMP' AS data_type, 12 AS ordinal_position), actual AS (
 SELECT table_name,column_name,data_type,ordinal_position,full_data_type,table_schema FROM workspace.information_schema.columns
 WHERE lower(table_schema)='default' AND lower(table_name) IN ('winterops_v2_dev_bronze','winterops_v2_dev_silver','winterops_v2_dev_manifest')), strict_actual AS (
 SELECT * FROM actual WHERE table_schema='default' AND table_name IN ('winterops_v2_dev_bronze','winterops_v2_dev_silver','winterops_v2_dev_manifest')), summary AS (
 SELECT (SELECT COUNT(*) FROM expected) AS expected_column_count,
 (SELECT COUNT(*) FROM actual) AS actual_column_count,
 (SELECT COUNT(*) FROM strict_actual) AS guard_actual_column_count,
 COUNT(*) AS guard_joined_rows,
 COUNT(CASE WHEN a.data_type=e.data_type AND a.ordinal_position=e.ordinal_position THEN 1 END) AS guard_matching_rows
 FROM expected e LEFT JOIN strict_actual a ON a.table_name=e.table_name AND a.column_name=e.column_name)
SELECT COALESCE(e.table_name,a.table_name) AS table_name,
 COALESCE(e.column_name,a.column_name) AS column_name,
 e.data_type AS expected_type, e.ordinal_position AS expected_ordinal_position,
 a.table_schema AS actual_table_schema, a.data_type AS actual_type, a.full_data_type AS actual_full_type,
 a.ordinal_position AS actual_ordinal_position,
 CASE WHEN e.column_name IS NULL THEN 'UNEXPECTED_COLUMN'
 WHEN a.column_name IS NULL THEN 'MISSING_COLUMN'
 WHEN NOT (a.data_type <=> e.data_type) AND NOT (a.ordinal_position <=> e.ordinal_position) THEN 'TYPE_AND_POSITION'
 WHEN NOT (a.data_type <=> e.data_type) THEN 'TYPE'
 WHEN NOT (a.ordinal_position <=> e.ordinal_position) THEN 'POSITION'
 ELSE 'MATCH' END AS match_status,
 summary.expected_column_count, summary.actual_column_count, summary.guard_actual_column_count,
 summary.guard_joined_rows, summary.guard_matching_rows
FROM expected e FULL OUTER JOIN actual a ON a.table_name=e.table_name AND a.column_name=e.column_name
CROSS JOIN summary
ORDER BY table_name,COALESCE(e.ordinal_position,a.ordinal_position),column_name;
